// Generates the embedded pages: the JSON inside a <script type="application/json">, as a server would embed it.
// `<` is escaped as < (valid JSON, and no `</script>` or `<!--` can end the element early).
//   embedded.html      from data/shoelace.json
//   embedded-x10.html  from data/shoelace-x10.json, a ten-times-larger copy written here too (`modules` repeated),
//                      to see where jank starts
// Run: node demo/benchmark/json/embed.mjs   (run.mjs does it first). The generated files are gitignored.
import fs from 'node:fs';

const here = new URL('./', import.meta.url);
const source = fs.readFileSync(new URL('../../data/shoelace.json', here), 'utf8');
const original = JSON.parse(source);
fs.writeFileSync(new URL('../../data/shoelace-x10.json', here),
    JSON.stringify({ ...original, modules: Array.from({ length: 10 }, () => original.modules).flat() }, null, 2));

for (const [name, page] of [['shoelace', 'embedded.html'], ['shoelace-x10', 'embedded-x10.html']]) {
    const json = fs.readFileSync(new URL(`../../data/${name}.json`, here), 'utf8');
    // The file as is (the same bytes fetch gets), with only `<` escaped
    const embedded = json.trim().replace(/</g, '\\u003c');
    const html = `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Approach 2: embedded JSON + JSON.parse</title>
    <script src="harness.js"></script>
    <style>body { font: 15px/1.5 system-ui, sans-serif; padding: 16px; } pre { background: #8881; padding: 8px; }</style>
</head>
<body>
    <h1>Approach 2: embedded JSON + JSON.parse</h1>
    <p><a href="./">All approaches</a> · Generated by embed.mjs from data/${name}.json (${(embedded.length / 1024).toFixed(0)} KB embedded)</p>
    <pre id="result">Loading…</pre>
    <script type="application/json" id="data">${embedded}</script>
    <script type="module">
        // Main thread: the HTML parser has read the JSON as text; JSON.parse turns it into objects
        const t0 = performance.now();
        const data = JSON.parse(document.getElementById('data').textContent);
        benchmarkDone({ step: performance.now() - t0, modules: data.modules.length, note: 'step: textContent + JSON.parse' });
    </script>
</body>
</html>
`;
    fs.writeFileSync(new URL(page, here), html);
    console.log(`${page}: ${(html.length / 1024).toFixed(0)} KB`);
}
